import { instant } from '@absoluteui/core';
import { Discussion, type DiscussionPostDetail, type DiscussionReplyDetail, type DiscussionDeleteDetail } from '@absoluteui/components/discussion';

const ada = { id: 'ada', name: 'Ada Lovelace' };
const grace = { id: 'grace', name: 'Grace Hopper' };
const host = document.createElement('div');
document.body.append(host);
Discussion.create(host, {
  label: 'Comments',
  currentUser: ada,
  maxLength: 500,
  comments: [
    { id: '1', parentId: null, author: grace, text: 'The new leave policy starts in January.', createdAt: instant(Date.UTC(2026, 10, 20, 9, 30)) },
    { id: '2', parentId: '1', author: ada, text: 'Thanks @Grace Hopper!', mentions: [{ id: 'grace', label: 'Grace Hopper', trigger: '@', start: 7, end: 20 }], createdAt: instant(Date.UTC(2026, 10, 20, 10)) },
  ],
});

// The host persists; the component has already added the comment optimistically.
host.addEventListener('aui-post', (event) => {
  const { comment } = (event as CustomEvent<DiscussionPostDetail>).detail;
  void fetch('/api/comments', { method: 'POST', body: JSON.stringify(comment) });
});
host.addEventListener('aui-reply', (event) => {
  const { comment } = (event as CustomEvent<DiscussionReplyDetail>).detail;
  void fetch('/api/comments', { method: 'POST', body: JSON.stringify(comment) });
});
host.addEventListener('aui-delete', (event) => {
  const { comment } = (event as CustomEvent<DiscussionDeleteDetail>).detail;
  void fetch(`/api/comments/${encodeURIComponent(comment.id)}`, { method: 'DELETE' });
});

import { instant } from '@absoluteui/core';
import { Discussion, type DiscussionPostDetail, type DiscussionComment } from '@absoluteui/components/discussion';

const host = document.createElement('div');
document.body.append(host);
const discussion = Discussion.create(host, { label: 'Ticket discussion', currentUser: { id: 'u1', name: 'Ana' } });

host.addEventListener('aui-post', (event) => {
  const { comment } = (event as CustomEvent<DiscussionPostDetail>).detail;
  // Prevented: nothing is added and the text stays in the box until the server answers.
  event.preventDefault();
  void fetch('/api/comments', { method: 'POST', body: JSON.stringify({ text: comment.text, mentions: comment.mentions }) })
    .then((response) => response.json() as Promise<{ id: string; createdAt: number }>)
    .then((saved) => {
      const stored: DiscussionComment = { ...comment, id: saved.id, createdAt: instant(saved.createdAt) };
      discussion.addComment(stored);
      discussion.composer?.reset();
    });
});

import { instant } from '@absoluteui/core';
import { Discussion, type DiscussionComment } from '@absoluteui/components/discussion';

const host = document.createElement('div');
document.body.append(host);
Discussion.create(host, {
  label: 'Forum thread',
  currentUser: { id: 'u1', name: 'Ana' },
  comments: [{ id: 't1', parentId: null, author: { id: 'u2', name: 'Ben' }, text: 'How do I export payslips?', createdAt: instant(Date.UTC(2026, 10, 18, 8)), replyCount: 42 }],
  loadReplies: async (comment, { signal, loaded }) => {
    const response = await fetch(`/api/comments/${encodeURIComponent(comment.id)}/replies?offset=${String(loaded)}&limit=20`, { signal });
    const rows = (await response.json()) as { id: string; author: { id: string; name: string }; text: string; createdAt: number }[];
    return rows.map((r): DiscussionComment => ({ id: r.id, parentId: comment.id, author: r.author, text: r.text, createdAt: instant(r.createdAt) }));
  },
});

import { plainDate } from '@absoluteui/core';
import { createBusinessCalendar } from '@absoluteui/components/business-calendar';
import { Discussion } from '@absoluteui/components/discussion';

const host = document.createElement('div');
document.body.append(host);
Discussion.create(host, {
  label: 'Leave request discussion',
  currentUser: { id: 'u1', name: 'Ana' },
  timezone: 'Europe/Berlin',
  businessCalendar: createBusinessCalendar({ holidays: [{ date: plainDate(2026, 12, 25), name: 'Christmas Day', yearly: true }] }),
  triggers: [{
    char: '@',
    label: '@ for people',
    provider: async (query, { signal }) => {
      const response = await fetch(`/api/people?q=${encodeURIComponent(query)}`, { signal });
      return (await response.json()) as { id: string; label: string }[];
    },
  }],
});
